// A decoder for the 32-bit x86 instructions that the original Blitz compilers generate (and a few more). Anything else is refused,
// so that unknown code is reported instead of being translated wrongly.
#pragma once
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

namespace blitz::recompiler::x86 {
	enum reg : int { EAX, ECX, EDX, EBX, ESP, EBP, ESI, EDI, NONE = -1 };

	enum class op {
		MOV, MOVZX, MOVSX, LEA, XCHG, PUSH, POP, NOP,
		ADD, OR, ADC, SBB, AND, SUB, XOR, CMP, TEST,
		INC, DEC, NEG, NOT, IMUL, MUL, IDIV, DIV, CDQ,
		SHL, SHR, SAR,
		JMP, JCC, CALL, RET, SETCC, SAHF,
		FLD, FILD, FST, FSTP, FISTP, FIST, FLD1, FLDZ, FXCH,
		FADDP, FSUBP, FSUBRP, FMULP, FDIVP, FDIVRP, FCHS, FABS, FUCOMPP, FNSTSW,
	};

	// The condition codes in the order of their encoding.
	enum class cc { O, NO, B, AE, E, NE, BE, A, S, NS, P, NP, L, GE, LE, G };

	struct operand {
		enum class kind { none, reg, imm, mem } type = kind::none;
		int      size  = 4;     // In bytes
		int      r     = NONE;  // reg: which. For size 1: 0-3 are al, cl, dl, bl; 4-7 ah, ch, dh, bh
		int32_t  value = 0;     // imm: the value (already extended)
		int      base  = NONE;  // mem: base register
		int      index = NONE;  // mem: index register
		int      scale = 1;
		int32_t  disp  = 0;
		int      pos   = -1;    // Where the 4 bytes of disp or imm are (offset in the code), when it has them, so that references there can be found
	};

	struct insn {
		uint32_t address = 0;
		uint32_t size    = 0;
		op       code    = op::NOP;
		cc       cond    = cc::E;
		operand  a, b, c;
		int      fpi     = 0;   // x87: the register number of the operation (st(i))
		uint32_t target  = 0;   // jumps and calls: the distance field position is in a.pos, a.value is the distance

		bool ends_block() const { return code == op::JMP || code == op::JCC || code == op::RET; }
	};

	struct bad_code : std::runtime_error {
		uint32_t address;
		bad_code(uint32_t address, std::string const& why) : std::runtime_error(why), address(address) {}
	};

	/** Decodes the instruction at `address`. Throws bad_code. */
	insn decode(std::vector<uint8_t> const& code, uint32_t address);

	char const* name(op o);
} // namespace blitz::recompiler::x86
